const { createRequire, builtinModules, isBuiltin } = require("module");
const constants = require("constants");
// Node.js's globals and module-level built-ins from an npm package: console, process as a
// module, performance, SharedArrayBuffer, createRequire, URL, V8's stack trace API. Prints what
// it found; the same package under Node.js prints the same.
module.exports = function run() {
  console.log("console", { a: 1, b: [1, 2] }, "x".repeat(3), 42);
  const p = require("process");
  console.log("process module", p === process, Object.keys(p).length > 10, Array.isArray(process.argv));
  const t = performance.now();
  console.log("performance", typeof t, t >= 0, performance.timeOrigin > 1e12, typeof PerformanceObserver);
  const sab = new SharedArrayBuffer(8);
  const view = new Int32Array(sab);
  Atomics.add(view, 0, 5);
  console.log("SharedArrayBuffer", sab.byteLength, Atomics.load(view, 0), Object.prototype.toString.call(sab));
  const req = createRequire(__filename);
  console.log("createRequire", req("path") === require("path"), req("./lib.js") === require("./lib"), req("./lib").name, isBuiltin("node:fs"), isBuiltin("nope"), builtinModules.includes("fs"));
  try {
    req("not-a-package");
  } catch (e) {
    console.log("createRequire missing", e.code);
  }
  console.log("constants", constants.O_RDONLY, constants.SIGTERM);
  const u = new URL("../b?x=1#h", "https://user@example.com:8080/a/c");
  u.searchParams.set("y", "2 3");
  console.log("URL", u.href, u.host, u.pathname, u.origin);
  const prev = Error.prepareStackTrace;
  Error.prepareStackTrace = (_, sites) => sites;
  const sites = new Error().stack;
  Error.prepareStackTrace = prev;
  console.log("callsites", typeof sites[0].getFileName(), sites[0].getFunctionName(), typeof sites[0].getLineNumber());
};
